SELECT nume, DECODE(bursa, NULL, 'fara', 'are') FROM studenti;
-- fara ×8, are ×5

SELECT nume, DECODE(bursa, 450, 'premiul 1') FROM studenti;
-- premiul 1 ×1, NULL ×12

SELECT CASE WHEN bursa = NULL THEN 'fara' ELSE 'are' END FROM studenti;
-- are ×13

SELECT CASE WHEN bursa IS NULL THEN 'fara' ELSE 'are' END FROM studenti;
-- fara ×8, are ×5

SELECT NVL(bursa / 50, 'lipsa') FROM studenti;
-- ORA-01722: invalid number

SELECT NVL(TO_CHAR(bursa / 50), 'lipsa') FROM studenti;
-- 9, 7, 5, ..., lipsa ×8

SELECT NVL(bursa / 50, '0') FROM studenti;
-- 0 ×8
